import { easeCubicInOut } from 'd3-ease';
import { interpolateNumber as interpolate } from 'd3-interpolate';

import {
  FnCanvasAccessor,
  BarCanvasInstance,
} from '../../types/canvas-shape.js';
import { areDatumsEqualBy } from '../datums.js';

/**
 * Check if current and prev bar canvas are equal.
 * By comparing all incoming data and isVertical prop from both.
 *
 * @param current - current bar canvas
 * @param prev - prev bar canvas
 * @returns boolean
 */
export function isBarCanvasEqual<Datum>(
  current: BarCanvasInstance<Datum>,
  prev: BarCanvasInstance<Datum>,
): boolean {
  if (
    !areDatumsEqualBy(current.data, prev.data, 'value') ||
    current.isVertical !== prev.isVertical
  ) {
    return false;
  }

  const isNotResizing =
    current.canvasWidth === prev.canvasWidth &&
    current.canvasHeight === prev.canvasHeight;

  if (isNotResizing) {
    return (
      prev.x(prev.data[0], 0) === current.x(current.data[0], 0) &&
      prev.y(prev.data[0], 0) === current.y(current.data[0], 0) &&
      current.width(current.data[0]) === prev.width(prev.data[0]) &&
      current.height(current.data[0]) === prev.height(prev.data[0])
    );
  }

  return true;
}

interface AnimationPoints<Datum> {
  start?: Datum;
  end: Datum;
}

/**
 * Get start and end points to be animated.
 *
 * @param canvas - current canvas, end
 * @param prevCanvas - previous canvas, start
 * @returns - array of start and end points store by current canvas (End) position
 */
function getAnimationPoints<Datum>(
  canvas: BarCanvasInstance<Datum>,
  prevCanvas?: BarCanvasInstance<Datum>,
) {
  const startEndPoints: AnimationPoints<Datum>[] = [];
  const dataLength = canvas.data.length;

  for (let i = 0; i < dataLength; i++) {
    const end = canvas.data[i];

    if (!prevCanvas) {
      startEndPoints.push({ start: undefined, end });

      continue;
    }

    const prevPoint = prevCanvas.data[i];

    startEndPoints.push({ start: prevPoint, end });
  }

  return startEndPoints;
}

/**
 * Vertical BarCanvas animation.
 * Bar animation logic based on elapsed, considering origin (prevCanvas) and end (canvas) points.
 * After all calculations, it will execute printBar callback
 *
 * @param barCanvas - current canvas, where the animation ends
 * @param prevBarCanvas - previous canvas, where the animation starts
 * @param elapsed - variable value, depends on animation laps
 * @param duration - animation duration(s) EG: 400 === 4ms
 * @param printBar - print bar call back
 */
export function barAnimation<Datum>(
  canvas: BarCanvasInstance<Datum>,
  progress: number,
  printBar: (
    x: FnCanvasAccessor<Datum>,
    y: FnCanvasAccessor<Datum>,
    w: FnCanvasAccessor<Datum>,
    h: FnCanvasAccessor<Datum>,
  ) => void,
  prevCanvas?: BarCanvasInstance<Datum>,
) {
  const animationPoints = getAnimationPoints<Datum>(canvas, prevCanvas);
  const interpolation = (start: number, end: number) =>
    interpolate(start, end)(easeCubicInOut(progress));

  // ADES-4720
  // TODO: Consider when layout change, do animation from ZeroAxis
  // TODO: StackedBars grow from previous series and should grow from ZeroAxis
  // const differentLayout = canvas.isVertical !== prevCanvas?.isVertical

  const x = (point: Datum, index: number) => {
    const { start, end } = animationPoints[index];

    if (canvas.isVertical) {
      return canvas.x(end, index);
    }

    if (start && prevCanvas) {
      return interpolation(prevCanvas.x(start, index), canvas.x(end, index));
    }

    return canvas.x(end, index);
  };

  const y = (point: Datum, index: number) => {
    const { start, end } = animationPoints[index];

    if (!canvas.isVertical) {
      return canvas.y(end, index);
    }

    if (start && prevCanvas) {
      return interpolation(prevCanvas.y(start, index), canvas.y(end, index));
    }

    return interpolation(canvas.zeroAxis(point), canvas.y(end, index));
  };

  const width = (point: Datum, index: number) => {
    const { start, end } = animationPoints[index];

    if (canvas.isVertical) {
      return canvas.width(end);
    }

    if (start && prevCanvas) {
      return interpolation(prevCanvas.width(start), canvas.width(end));
    }

    return canvas.width(end);
  };

  const height = (point: Datum, index: number) => {
    const { start, end } = animationPoints[index];

    if (!canvas.isVertical) {
      return canvas.height(end);
    }

    if (start && prevCanvas) {
      return interpolation(prevCanvas.height(start), canvas.height(end));
    }

    return canvas.height(end);
  };

  return printBar(x, y, width, height);
}
